var headers, rows;
if (Array.isArray(input.headers) && Array.isArray(input.rows)) { headers = input.headers; rows = input.rows; }
else if (typeof input.csv === "string") {
  var text = input.csv;
  var lines = text.split(/\r?\n/).filter(function (l) { return l.trim() !== ""; });
  function splitRow(line) {
    var out = []; var cur = ""; var inQ = false;
    for (var i = 0; i < line.length; i++) {
      var ch = line[i];
      if (inQ) { if (ch === "\"") { if (line[i + 1] === "\"") { cur += "\""; i++; } else { inQ = false; } } else { cur += ch; } }
      else if (ch === "\"") { inQ = true; }
      else if (ch === ",") { out.push(cur); cur = ""; }
      else { cur += ch; }
    }
    out.push(cur);
    return out;
  }
  var parsed = lines.map(splitRow);
  headers = parsed[0] || []; rows = parsed.slice(1);
} else { throw new Error("csv-stats needs headers+rows or csv"); }
var means = {};
var count = rows.length;
(headers || []).forEach(function (h, i) {
  var nums = rows.map(function (r) { return Number(r[i]); }).filter(function (n) { return !isNaN(n); });
  if (nums.length > 0) {
    var s = 0; nums.forEach(function (n) { s += n; });
    means[h] = Math.round((s / nums.length) * 100) / 100;
  }
});
return { count: count, columns: headers, means: means };
